module accu(
    input clk, input rst_n, input [7:0] data_in, input valid_in,
    output reg valid_out, output reg [9:0] data_out
);
    parameter s0 = 2'b00;
    parameter s1 = 2'b01;
    parameter s2 = 2'b10;
    parameter s3 = 2'b11;
    reg [1:0] state, next_state;
    reg [1:0] count;
    reg [9:0] sum;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= s0;
            count <= 2'b00;
            sum <= 10'b0;
        end else begin
            state <= next_state;
            if (valid_in) begin
                case (state)
                    s0: begin
                        sum <= data_in;
                        count <= 2'b01;
                        next_state <= s1;
                    end
                    s1: begin
                        sum <= sum + data_in;
                        count <= count + 1;
                        if (count == 2'b10) next_state <= s2;
                        else next_state <= s1;
                    end
                    s2: begin
                        sum <= sum + data_in;
                        count <= count + 1;
                        if (count == 2'b11) next_state <= s3;
                        else next_state <= s2;
                    end
                    s3: begin
                        sum <= sum + data_in;
                        count <= 2'b00;
                        next_state <= s0;
                    end
                endcase
            end else begin
                next_state <= state;
            end
        end
    end
    always @(*) begin
        if (state == s3) valid_out = 1;
        else valid_out = 0;
        data_out = sum;
    end
endmodule
